package com.pulseride.gateway;
import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.cloud.gateway.config.GlobalCorsProperties; import org.springframework.context.annotation.*;
@Configuration public class GatewayCorsConfig { @Bean GlobalCorsProperties cors(@Value("${cors.allowed-origins:http://localhost:5173}") String origins) { var config=new org.springframework.web.cors.CorsConfiguration(); config.setAllowedOrigins(Arrays.stream(origins.split(",")).map(String::trim).toList()); config.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS")); config.setAllowedHeaders(List.of("Authorization","Content-Type","Accept","Origin","X-Requested-With","Idempotency-Key")); config.setExposedHeaders(List.of("Location")); config.setAllowCredentials(true); config.setMaxAge(3600L); var props=new GlobalCorsProperties(); props.getCorsConfigurations().put("/**",config); return props; } }
